$node_obj = entity_metadata_wrapper('node', $node);

$max_hourly_rate = $node_obj->field_maximum_hourly_rate->value(); // EUR/hour

$eur_basket = $node_obj->field_euro_basket->value();
$chr_basket = $node_obj->field_chron_basket->value();
$old_cache_val = $node_obj->field_chron_basket_cache->value() != NULL ? $node_obj->field_chron_basket_cache->value() : 0;
$comp_max_hourly_rate = $chr_basket > 0 ? $eur_basket / ($chr_basket/10) : 0;


//calculate the number of (negative) chrons we need to add to the cache
$diff = ($eur_basket * 10)/$max_hourly_rate - $chr_basket;

if ($comp_max_hourly_rate > $max_hourly_rate) {

	//add some chrons from cache to the basket, to enforce the max. hourly rate
	$new_cache_val = $old_cache_val - $diff;
	$node_obj->field_chron_basket_cache->set($new_cache_val);

	$new_chr_basket = $chr_basket + $diff;
	$node_obj->field_chron_basket->set($new_chr_basket);

	$node_obj->save();
}
else if ($old_cache_val < 0 && $comp_max_hourly_rate < $max_hourly_rate) {

	if (abs($diff) < abs($old_cache_val)) {
		$node_obj->field_chron_basket->set($chr_basket + $diff);
		$node_obj->field_chron_basket_cache->set($old_cache_val - $diff);
	}
	else {
		$node_obj->field_chron_basket->set($chr_basket + $old_cache_val);
		$node_obj->field_chron_basket_cache->set(0);
	}
	$node_obj->save();
}
